-- BLUEPRINT FINAL DO HUB DE PROJETOS (CEO 23/10, Eng. Chefe 2 / Fable 5.1) — dados de PLANEJAMENTO, idempotente.
-- Fonte: exemplos reais FC_PISOS_4.pdf (acerto de viagem) e CPP_BRF.pdf (tabela de preços contratada), Blueprint v5,
-- auditoria PDCA de 23/10 e pesquisa de mercado 2026. Doc: projeto › claude/hub-projetos-visao-e-blueprint-2026-10-23.md.
-- Toca só blueprint_tela_requisito (vertical hub_projetos) e ge_roadmap_ondas (200–216). Nenhum dado de cliente.
-- Os INSERTs já foram aplicados por hotfix em 23/10 (ON CONFLICT DO NOTHING mantém a reprodutibilidade);
-- os UPDATEs são aplicados por esta migration (o CEO escolheu a via migration — opção B).

-- ───────────────────────── 1) Requisitos novos: módulos genéricos (viagens, relatório de custo, contrato de preços, medição) ─────
INSERT INTO public.blueprint_tela_requisito (vertical, tela_num, tela_nome, rota_padrao, requisito, tipo, prioridade, status_baseline, evidencia_baseline)
SELECT 'hub_projetos', t.n, t.nome, t.rota, t.req, t.tipo, t.prio, 'ausente', t.ev FROM (VALUES
(270,'PS · HB1 · Viagens e deslocamento (prestação de contas)','/dashboard/projetos/viagens','Viagem da equipe vinculada à obra/etapa (centro de custo): colaboradores, veículo (placa, do PS Frota), período, origem→destino, finalidade, km inicial/final com foto do hodômetro — criada em 1 toque a partir da obra.','tela','essencial','Caso FC_PISOS_4 (acerto de viagem). Serve a toda empresa que desloca equipe. RD-96: leiaute PS.'),
(270,'PS · HB1 · Viagens e deslocamento (prestação de contas)','/dashboard/projetos/viagens','Despesas da viagem por tipo (alimentação, hospedagem, pedágio, combustível, outras) com foto do comprovante, fornecedor, data, nº do cupom e quem pagou (empresa, cartão corporativo ou colaborador) — lançadas pelo celular ou pelo WhatsApp (HB-W).','regra','essencial','FC_PISOS_4: 13 registros de alimentação + outras, "pago mot." Sim/Não.'),
(270,'PS · HB1 · Viagens e deslocamento (prestação de contas)','/dashboard/projetos/viagens','Abastecimento na viagem: posto, litros, R$/litro, hodômetro, tanque cheio → consumo médio (km/l) e custo por km, integrado ao PS Frota (veículo e manutenção).','regra','essencial','FC_PISOS_4: 2 abastecimentos, 116,37 l, média 7,96 km/l, custo/km 6,64.'),
(270,'PS · HB1 · Viagens e deslocamento (prestação de contas)','/dashboard/projetos/viagens','Adiantamento e prestação de contas: adiantamento − despesas pagas pelo colaborador = saldo (reembolso a pagar ou devolução), aprovação do gestor no celular, gera título na GE (contas a pagar/reembolso) e concilia o cartão corporativo. Assinatura eletrônica do colaborador.','regra','essencial','FC_PISOS_4: "saldo da prestação" −R$ 4.401,67, assinatura do motorista. Financeiro pela GE (RD-35).'),
(270,'PS · HB1 · Viagens e deslocamento (prestação de contas)','/dashboard/projetos/viagens','Apropriação automática: toda despesa aprovada vira custo da obra na GE na categoria "Deslocamento e viagem" (subtipos), e aparece no Cockpit, no Resultado por obra e no relatório de custo. Mobilização/desmobilização por faixa de km também como item de orçamento e de medição.','regra','essencial','CPP_BRF cobra mobilização por faixa de km (até 200/500/1.000/+1.000 km) — custo e receita se encontram na obra.'),
(270,'PS · HB1 · Viagens e deslocamento (prestação de contas)','/dashboard/projetos/viagens','Indicadores da viagem: custo de viagem por m² executado, por km e por dia de equipe; alerta quando a viagem passa de X% do orçado da obra; histórico por rota para orçar a próxima mobilização.','kpi','diferencial','Inteligência própria PS: a FC orça mobilização por faixa de km; o histórico real calibra o preço.'),
(270,'PS · HB1 · Viagens e deslocamento (prestação de contas)','/dashboard/projetos/viagens','"?" em todo campo (RD-95) em linguagem de quem está na estrada; funciona offline no celular; fechamento da viagem em ≤3 toques; nada irreversível sem prévia e desfazer.','visual','essencial','Padrão PS (RD-95/RD-96).'),
(271,'PS · HB1 · Relatório de custo da obra','/dashboard/projetos/obras/resultado','Relatório de custo da obra por período: orçado × realizado por categoria (material, mão de obra, viagens e deslocamento, equipamentos, subempreiteiros, outros), por etapa/serviço, com drill-down até o lançamento e o comprovante; exportável PDF/XLS e enviável ao cliente pelo portal. Leiaute PS, nunca o do sistema anterior.','tela','essencial','Pedido do Diego (FC Pisos) para 01/11; substitui o relatório do DotSE. RD-96.'),
(271,'PS · HB1 · Relatório de custo da obra','/dashboard/projetos/obras/resultado','Comparativo entre obras e entre períodos (custo/m², custo/dia, viagem/m²) e fotografia mensal guardada (não muda depois de fechada).','kpi','diferencial','Base do benchmark da Rede PS (HB-R).'),
(272,'PS · HB2 · Contrato de preços do cliente','/dashboard/projetos/tabelas-preco','Tabela de preços contratada por cliente (e por obra/unidade do cliente): serviço do catálogo × unidade × faixas de quantidade × regime de execução (dia útil, noturno, sábado, domingo/feriado — % ou valor por regime) × código do item no ERP do cliente × vigência e reajuste por índice; versões com diferença visível.','tela','essencial','Caso CPP_BRF (faixas até 100 … +10.000 m²; regimes +20/+50/+100%; códigos SAP). Genérico para qualquer tomador. RD-96.'),
(272,'PS · HB2 · Contrato de preços do cliente','/dashboard/projetos/tabelas-preco','Importar a tabela do cliente de Excel/PDF com IA (mapeando colunas, faixas, regimes e códigos), sempre com revisão lado a lado antes de gravar.','regra','essencial','CPP_BRF chega em PDF de 3 páginas; digitar à mão é erro certo.'),
(272,'PS · HB2 · Contrato de preços do cliente','/dashboard/projetos/tabelas-preco','De-para serviço PS ↔ item/código do cliente, com aviso de serviço sem código e de código sem serviço; o mesmo de-para alimenta orçamento, medição e NF.','regra','essencial','CPP_BRF: cada regime tem código próprio (ex.: 532539 / 533089 / 533126 / 533152).'),
(272,'PS · HB2 · Contrato de preços do cliente','/dashboard/projetos/tabelas-preco','Precedência de preço mostrada no item do orçamento: contrato do cliente > tabela por cliente > tabela padrão, com o motivo em linguagem simples.','regra','essencial','Supera Simpro (níveis de preço) com a origem explicada.'),
(272,'PS · HB2 · Contrato de preços do cliente','/dashboard/projetos/tabelas-preco','Simulador do contrato: dado um serviço, quantidade e regime, mostra a faixa e o preço que valerá na medição — para vendedor e cliente conferirem antes de executar.','tela','diferencial','Facilidade PS: zero planilha paralela.'),
(273,'PS · HB5 · Medição ao cliente pela tabela contratada','/dashboard/projetos/obras/resultado','Medição automática: apontamento de produção por serviço/local/turno (campo ou WhatsApp) → quantidade acumulada no período → faixa → regime → preço contratado → extrato de medição nos códigos do cliente, com memória de cálculo por linha e aprovação no celular.','regra','essencial','CPP_BRF: o preço depende de faixa e regime; só o apontamento por turno permite medir certo. Automação "apontamento → medição → título na GE".'),
(273,'PS · HB5 · Medição ao cliente pela tabela contratada','/dashboard/projetos/obras/resultado','Pacote de medição ao tomador: extrato por área/serviço + resumo do RDO (equipe, horas, ocorrências) + fotos + documentação SST (ASO/NR pela PS EHS), PDF/XLS, enviado pelo portal do cliente; vira título/NF na GE.','tela','essencial','Exigência típica de tomadores industriais (caso BRF).'),
(273,'PS · HB5 · Medição ao cliente pela tabela contratada','/dashboard/projetos/obras/resultado','Travas honestas: executado em regime sem preço no contrato, acima da última faixa, sem código do cliente ou sem foto obrigatória → a medição avisa e não deixa medir errado (sem bloquear o apontamento).','guard','essencial','Super sincero: número errado na frente do cliente é inaceitável.'),
(273,'PS · HB5 · Medição ao cliente pela tabela contratada','/dashboard/projetos/obras/resultado','Medição acumulada × contrato: saldo contratado − medido por item, previsão de fechamento e alerta de item esgotando.','kpi','diferencial','Mesma lógica do saldo orçado − comprado (HB1).'),
-- visão "a obra que se conta sozinha"
(274,'PS · HB-C · Núcleo de custo e margem viva','/dashboard/projetos/obras/resultado','Apropriação única por lançamento vinda da GE (compra, NF, apontamento, viagem, equipamento, subempreiteiro) por obra/etapa/serviço — o Hub não tem silo de custo.','regra','essencial','RD-35. Antecipa o coração da HB6 para rodar desde a HB1.'),
(274,'PS · HB-C · Núcleo de custo e margem viva','/dashboard/projetos/obras/resultado','Orçado × comprometido × realizado × a incorrer por obra, ao vivo, no Cockpit e no Resultado; margem viva e caixa da obra com INCC.','kpi','essencial','Hoje o Cockpit da DEMO está zerado por falta disso (auditoria 23/10).'),
(274,'PS · HB-C · Núcleo de custo e margem viva','/dashboard/projetos/obras/resultado','"Se eu terminar hoje, quanto sobra?": previsão até o fim com causa provável do desvio (material, mão de obra, viagem, prazo) e o que fazer, em linguagem simples.','tela','essencial','Automação "desvio → alerta com causa" já mapeada; aqui vira a pergunta que o dono de obra faz.'),
(274,'PS · HB-C · Núcleo de custo e margem viva','/dashboard/projetos/obras/resultado','Semáforo do dinheiro da obra: verde/amarelo/vermelho por obra no painel e na lista, com o motivo e o item que mais pesa.','visual','essencial','Facilidade PS: decisão em 1 olhar.'),
(274,'PS · HB-C · Núcleo de custo e margem viva','/dashboard/projetos/obras/resultado','Todo número do Hub é conferível contra um caso conhecido na DEMO (ticker de qualidade com critério "cálculo correto") antes de liberar a tela.','guard','essencial','Critério de Gold (CEO 23/10).'),
(275,'PS · HB-W · Canteiro por WhatsApp e voz','/dashboard/projetos/campo','Canal da obra no WhatsApp: áudio, foto, vídeo ou PDF enviados pela equipe viram, com IA, RDO, apontamento de produção por turno, despesa/viagem, pedido de material, serviço extra ou ocorrência de segurança — cada item volta como card "confirma?" em 1 toque; nada entra sem confirmação.','tela','essencial','Mercado 2026: Vobi (3 agentes por WhatsApp), Prevision (consulta). PS supera por nascer dentro do ERP fiscal/financeiro (GE) e da SST (PS EHS). RD-96.'),
(275,'PS · HB-W · Canteiro por WhatsApp e voz','/dashboard/projetos/campo','Voz no app de campo (offline): ditar RDO, apontamento ou ocorrência; transcrição e estruturação acontecem ao sincronizar.','regra','essencial','Mesmo app do Campo Digital da PS EHS.'),
(275,'PS · HB-W · Canteiro por WhatsApp e voz','/dashboard/projetos/campo','Pergunte à obra pelo WhatsApp: "quanto gastei esta semana?", "o que falta no estoque?", "a obra X está atrasada?" — resposta com link para o item e a evidência, só para papéis autorizados.','regra','essencial','Agentes desde a HB-W (não mais HB9).'),
(275,'PS · HB-W · Canteiro por WhatsApp e voz','/dashboard/projetos/campo','Identidade e permissão por número de telefone vinculado ao colaborador e à obra; LGPD: consentimento, retenção pelo prazo do contrato, fotos de pessoas tratadas como dado sensível.','guard','essencial','Cautela PS.'),
(275,'PS · HB-W · Canteiro por WhatsApp e voz','/dashboard/projetos/campo','Custo de IA por empresa com teto e contador visível; liga só com cliente bancando (RD-42); falha não cobra.','guard','essencial','RD-42.'),
(275,'PS · HB-W · Canteiro por WhatsApp e voz','/dashboard/projetos/campo','Piloto com casos reais (Tryo e FC Pisos) antes de generalizar; meta: 80% dos lançamentos de campo entrando por WhatsApp/voz sem retrabalho.','regra','essencial','Super sincero: nada é prometido sem piloto.'),
(276,'PS · HB-F · Progresso por foto e evidência','/dashboard/projetos/campo','Foto do serviço no local (celular comum, sem câmera 360 nem BIM) + catálogo PS → % de avanço por serviço/local comparado ao cronograma; a IA propõe, o encarregado confirma.','tela','diferencial','Mercado 2026: Buildots/OpenSpace/Doxel/Track3D exigem 360/BIM; PS faz com o celular. Obra típica entrega 63% do planejado por semana (Buildots 10/2026).'),
(276,'PS · HB-F · Progresso por foto e evidência','/dashboard/projetos/campo','Fotos viram evidência da medição ao cliente e ao empreiteiro (ligadas à linha do extrato) e do relatório fotográfico do RDO.','regra','essencial','Caso BRF: medição com fotos.'),
(276,'PS · HB-F · Progresso por foto e evidência','/dashboard/projetos/campo','Linha do tempo visual da obra por local (antes/depois), com comparação entre datas.','visual','diferencial','Evercam-like sem câmera fixa.'),
(277,'PS · HB-R · Rede PS (benchmark entre clientes)','/dashboard/projetos','Benchmark anônimo e agregado entre clientes PS: produtividade (RUP) por serviço, preço de insumo por região, % de entrega semanal, custo de viagem por m² — "sua obra vs. o mercado PS"; opt-in por empresa, mínimo de N empresas por indicador, nunca identificável.','tela','diferencial','Ninguém no Brasil tem com dado real de canteiro. Efeito de rede defensável. LGPD/segredo comercial.'),
(277,'PS · HB-R · Rede PS (benchmark entre clientes)','/dashboard/projetos','Sugestão de preço e de produtividade no orçamento com base na rede (com faixa e confiança), sempre editável.','regra','diferencial','Fecha o ciclo orçamento → realizado → próximo orçamento.'),
(277,'PS · HB-R · Rede PS (benchmark entre clientes)','/dashboard/projetos','Gatilho: liga quando houver ≥3 empresas com dado de canteiro suficiente; relatório trimestral "Mercado PS de obras".','guard','diferencial','Decisão do CEO.'),
(278,'PS · HB-P · Compliance que paga (fintech embutida)','/dashboard/projetos/obras/os','Medição do empreiteiro aprovada no celular → título na GE → pagamento por Pix/boleto dentro do fluxo, com retenções (INSS/ISS/IR) e caução automáticas.','regra','essencial','Procore Pay à brasileira. Financeiro pela GE.'),
(278,'PS · HB-P · Compliance que paga (fintech embutida)','/dashboard/projetos/obras/os','Só paga com documentação válida: certidões, seguro, ASO/NR/EPI pela PS EHS; aviso de quem regulariza e do que vence antes da próxima medição.','guard','essencial','Lacuna registrada (Procore só em parte). Trava já mapeada na HB5 (Senior).'),
(278,'PS · HB-P · Compliance que paga (fintech embutida)','/dashboard/projetos/obras/os','Antecipação de recebíveis da obra e cartão corporativo da equipe como opções com custo à vista (gatilho RD-42).','regra','diferencial','RD-42.'),
(279,'PS · HB9 · IA transversal e manual vivo','/dashboard/projetos','Assistente da obra em toda tela desde a HB-W: responde com link para o item e evidência; propõe ação com motivo e impacto; só executa com aceite humano.','regra','essencial','Doutrina HB9 mantida; a onda deixa de ser a última.'),
(279,'PS · HB9 · IA transversal e manual vivo','/dashboard/projetos','Manual vivo por tela gerado automaticamente ao virar Gold: print do auditor + textos "?" (erp_ajuda_campo) + propósito e caminho principal; atualiza a cada auditoria; disponível no "?" da tela e no portal.','regra','essencial','CEO 23/10: manual super dinâmico a partir do auditor.'),
(279,'PS · HB9 · IA transversal e manual vivo','/dashboard/projetos','Relatórios por pergunta cruzando obras e ferramentas, com a consulta explicada e salvável como painel.','tela','diferencial','Procore 360 Reporting adotado com linguagem PS.'),
(280,'PS · HB7 · Portais sem assento','/dashboard/projetos/obras','Cliente, empreiteiro, fornecedor, encarregado e corretor entram por link/QR com código temporário, sem licença por usuário; cada um vê só a sua obra e o seu papel.','tela','essencial','Atrito nº 1 do mercado global em 2026 (licença por assento deixa sub/fornecedor/cliente fora do sistema).'),
(280,'PS · HB7 · Portais sem assento','/dashboard/projetos/obras','Portal do cliente: andamento, fotos, medições, boletos, documentos e chamados; QR na obra entregue abre chamado de garantia.','tela','essencial','Sienge/Auvo adotados; leiaute PS.'),
(281,'PS · HB3 · Replanejamento por IA','/dashboard/projetos/obras','Atraso detectado (RDO/foto/apontamento) → a IA propõe a nova programação da semana e a realocação de equipe, com impacto em prazo e custo; o gestor aceita, edita ou recusa.','regra','diferencial','Agilean Copilot / Procore Gantt recommendations (2026). Aceite humano sempre.'),
(282,'PS · HB4 · Telemática e km automático','/dashboard/projetos/viagens','Km pela rota entre serviços (GPS do app, com consentimento e só na jornada), mapa único de equipamentos próprios e locados com alerta de devolução e preventiva prevista por uso.','regra','diferencial','Auvo (km por rota) e Yardz/IVO (telemática) 2026; LGPD.'),
(283,'PS · HB6 · ESG da obra','/dashboard/projetos/obras/resultado','CO2 estimado por insumo (fator por unidade), resíduos e CTR por obra, relatório para licitação e incorporadora; nasce do orçamento e do consumo real, sem lançamento extra.','kpi','diferencial','Exigência crescente de incorporadoras e licitações; não mapeado em nenhum concorrente benchmarkado.'),
(284,'PS · Comercial · Usuários ilimitados no Hub','/dashboard/projetos','Modelo comercial do Hub com usuários ilimitados por empresa (papéis por função), para o canteiro inteiro e os parceiros estarem dentro do sistema de registro.','regra','diferencial','Decisão do CEO. Acumatica/IVO 2026 usam isso como diferencial; Procore é criticado pelo assento.')
) AS t(n, nome, rota, req, tipo, prio, ev)
ON CONFLICT (vertical, tela_num, requisito) DO NOTHING;

-- ───────────────────────── 2) As 2 linhas de 23/10 (eram hipótese) passam a refletir os PDFs reais ─────────────────────────
UPDATE public.blueprint_tela_requisito SET
  requisito = 'PILOTO FC Pisos (01/11): o "acerto de viagem" hoje feito fora do ERP (viagem nº, motorista/equipe, placa, período, origem→destino, km inicial/final, abastecimentos com litros e R$/l, despesas por tipo com nº do cupom, "pago pelo colaborador", saldo da prestação de contas, custo por km) passa a ser lançado e FECHADO no Hub, apropriado à obra, e o relatório de custo da obra sai no leiaute PS para o Diego.',
  evidencia_baseline = 'Exemplo real FC_PISOS_4.pdf (acerto de viagem 471, 06–17/07/2026, Iporã do Oeste/SC → Promissão/SP, 926 km, 13 despesas R$ 4.115,57, saldo −R$ 4.401,67, custo/km R$ 6,64) enviado pelo CEO em 23/10. Vira o módulo genérico "Viagens e deslocamento" (tela 270). Leiaute exclusivo PS (RD-96).'
WHERE id = '26e104d7-10a1-4bbc-b81e-a239c52b059e';

UPDATE public.blueprint_tela_requisito SET
  tela_nome = 'FC Pisos (cliente) · HB5 · Medição à BRF pela tabela contratada',
  requisito = 'PILOTO BRF/FC Pisos: a tabela de preços contratada da BRF (serviço × unidade × faixa de quantidade até 100/500/1.000/5.000/10.000 m² × regime dia útil / noturno +20% / sábado +50% / domingo-feriado +100% × código SAP de material, inclusive mobilização/desmobilização por faixa de km) é cadastrada como "Contrato de preços do cliente", e a medição à BRF é gerada automaticamente do apontamento de produção por turno, nos códigos dela, com memória de cálculo, fotos e documentação SST.',
  evidencia_baseline = 'Exemplo real CPP_BRF.pdf (3 páginas: uretano 6/10/12 mm, auto-nivelante, rodapé, multilayer, pinturas, epóxi, preparação de base, juntas, descontaminação, caimento, reparos, mobilização por km; 4 regimes com código SAP próprio) enviado pelo CEO em 23/10. Vira os módulos genéricos "Contrato de preços do cliente" (tela 272) e "Medição ao cliente pela tabela" (tela 273). Leiaute exclusivo PS (RD-96).'
WHERE id = '0294f077-6b6b-44d4-af50-bb3db48ca990';

-- ───────────────────────── 3) Ondas novas (aditivas) ─────────────────────────
INSERT INTO public.ge_roadmap_ondas (numero, nome, objetivo, status, duracao_semanas, ordem_prioridade, observacoes) VALUES
 (212,'HB-C · Núcleo de custo e margem viva','Apropriação única vinda da GE por obra/etapa/serviço; orçado × comprometido × realizado × a incorrer ao vivo; margem viva e caixa da obra; "se eu terminar hoje, quanto sobra?" com causa provável; semáforo do dinheiro por obra; todo número conferível na DEMO antes de liberar.','planejada',2,3,'Antecipa o coração da HB6 para rodar desde a HB1/HB2 (CEO 23/10: o custo é a 1ª coisa que o dono de obra sente; Cockpit da DEMO zerado na auditoria de 23/10).'),
 (213,'HB-W · Canteiro por WhatsApp e voz (a obra que se conta sozinha)','Áudio/foto/vídeo/PDF pelo WhatsApp e voz no app viram RDO, apontamento por turno, despesa/viagem, pedido, serviço extra e ocorrência — card "confirma?" em 1 toque; "pergunte à obra"; identidade por telefone, LGPD, teto de custo de IA (RD-42). Piloto Tryo/FC.','planejada',4,6,'Transversal: alimenta HB1 (viagens), HB-C (custo), HB4 (campo), HB5 (medição). Supera Vobi por estar dentro da GE + PS EHS. RD-96: leiaute e nomes PS.'),
 (214,'HB-F · Progresso por foto e evidência','Foto do serviço no local (celular comum) + catálogo → % avanço por serviço/local vs cronograma, IA propõe e encarregado confirma; fotos como evidência da medição ao cliente/empreiteiro; linha do tempo visual por local.','planejada',3,10,'Sem câmera 360 nem BIM (diferente de Buildots/OpenSpace/Doxel). Caso BRF: medição com fotos.'),
 (215,'HB-R · Rede PS (benchmark entre clientes)','Benchmark anônimo e agregado: RUP por serviço, preço de insumo por região, % entrega semanal, custo de viagem por m²; sugestão de preço/produtividade no orçamento; relatório "Mercado PS de obras".','planejada',3,14,'GATILHO: ≥3 empresas com dado de canteiro. Opt-in, mínimo N, nunca identificável. Efeito de rede defensável — ninguém no Brasil tem.'),
 (216,'HB-P · Compliance que paga (fintech embutida)','Medição aprovada → título GE → Pix/boleto no fluxo, retenções e caução automáticas; só paga com documentação válida (certidões, ASO/NR pela PS EHS); antecipação de recebíveis e cartão corporativo como opções (RD-42).','planejada',3,15,'GATILHO RD-42. Procore Pay à brasileira. Financeiro sempre pela GE.')
ON CONFLICT (numero) DO NOTHING;

-- ───────────────────────── 4) Ondas existentes: objetivo ampliado (só acréscimo) e HB9 transversal ─────────────────────────
UPDATE public.ge_roadmap_ondas SET objetivo = objetivo || ' + VIAGENS E DESLOCAMENTO da equipe (prestação de contas por obra: km, abastecimento, despesas com foto, adiantamento/reembolso → GE) com linha própria no Resultado por obra e no relatório de custo (Diego, 01/11).' WHERE numero=201 AND objetivo NOT ILIKE '%VIAGENS E DESLOCAMENTO%';
UPDATE public.ge_roadmap_ondas SET objetivo = objetivo || ' + CONTRATO DE PREÇOS DO CLIENTE (tabela por cliente/obra: faixas de quantidade, regimes dia útil/noturno/sábado/domingo-feriado, códigos do ERP do cliente, vigência/reajuste; importada por IA; simulador) — genérico, caso BRF/FC Pisos.' WHERE numero=202 AND objetivo NOT ILIKE '%CONTRATO DE PREÇOS DO CLIENTE%';
UPDATE public.ge_roadmap_ondas SET objetivo = objetivo || ' + replanejamento da semana proposto por IA (aceite humano).' WHERE numero=204 AND objetivo NOT ILIKE '%replanejamento%';
UPDATE public.ge_roadmap_ondas SET objetivo = objetivo || ' + km automático pela rota (consentimento) e telemática/equipamento preditivo.' WHERE numero=205 AND objetivo NOT ILIKE '%telemática%';
UPDATE public.ge_roadmap_ondas SET objetivo = objetivo || ' + MEDIÇÃO AO CLIENTE AUTOMÁTICA pela tabela contratada (apontamento por serviço/local/turno → faixa → regime → preço → extrato nos códigos do cliente, com RDO, fotos e SST; PDF/XLS, portal; vira título/NF na GE) e travas que não deixam medir errado.' WHERE numero=206 AND objetivo NOT ILIKE '%MEDIÇÃO AO CLIENTE AUTOMÁTICA%';
UPDATE public.ge_roadmap_ondas SET objetivo = objetivo || ' + ESG da obra (CO2 por insumo, resíduos/CTR) e comparativo entre obras.' WHERE numero=207 AND objetivo NOT ILIKE '%ESG%';
UPDATE public.ge_roadmap_ondas SET objetivo = objetivo || ' + PORTAIS SEM ASSENTO (cliente, empreiteiro, fornecedor, encarregado, corretor por link/QR, sem licença por usuário).' WHERE numero=208 AND objetivo NOT ILIKE '%PORTAIS SEM ASSENTO%';
UPDATE public.ge_roadmap_ondas SET
  objetivo = 'TRANSVERSAL desde a HB-W (não é mais a última onda): assistente da obra em toda tela ("pergunte à obra") com link e evidência; agentes (RFI, diário, contrato, cobrança); relatórios por pergunta; MANUAL VIVO por tela gerado do auditor ao virar Gold (print + "?" + propósito). IA propõe com motivo e impacto e só muda com aceite humano.',
  observacoes = 'CEO 23/10: a IA é a porta de entrada do canteiro, não um módulo final. Cresce a cada onda a partir da HB-W.'
WHERE numero=210 AND objetivo NOT ILIKE 'TRANSVERSAL desde a HB-W%';

-- ───────────────────────── 5) Sequência final das 17 ondas do Hub ─────────────────────────
UPDATE public.ge_roadmap_ondas SET ordem_prioridade = v.o FROM (VALUES
 (200,1),(201,2),(212,3),(202,4),(203,5),(213,6),(210,7),(204,8),(205,9),(214,10),(206,11),(207,12),(208,13),(215,14),(216,15),(209,16),(211,17)
) AS v(n,o) WHERE ge_roadmap_ondas.numero = v.n;
